    geo:"에브라임·므낫세 산지 — 에발 산(940m)·그리심 산(881m) 사이. 이스라엘 중부의 핵심 산악지대로 빽빽한 숲과 계단식 경작지가 발달했다. 강수량이 풍부해 가나안 정착 초기 가장 인구가 많고 비옥한 지파 영토였다 | 고도: 약 550m",
