       bg:"왕정 수립기의 격변 속에서 헤브론에서 7년 6개월 유다 왕 통치를 둘러싸고 벌어진 일이다. 다윗이 헤브론으로 올라가 유다 지파에게 왕으로 기름 부음을 받음. 7년 6개월 후 예루살렘으로 천도.",
