       ref:"창 32:24-32",
       bg:"족장·기원 시대를 배경으로 하나님과 씨름, 이스라엘 개명을 둘러싸고 벌어진 일이다. 얍복 강가에서 동이 틀 때까지 씨름. 하나님이 야곱의 환도뼈를 침. 야곱이 축복을 구함. 이름이 야곱(발꿈치를 잡는 자)에서 이스라엘(하나님과 겨루어 이긴 자)로 바뀜.",
