       ref:"창 21:22-34",
       bg:"족장·기원 시대를 배경으로 브엘세바 우물 계약, 에셀 나무를 둘러싸고 벌어진 일이다. 아브라함과 블레셋 왕 아비멜렉이 우물 문제로 계약. 브엘세바(맹세의 우물)라 이름함. 아브라함이 에셀 나무를 심고 하나님의 이름을 불러 예배.",
