       ref:"창 26:23-33",
       bg:"족장·기원 시대를 배경으로 이삭에게 나타나신 하나님을 둘러싸고 벌어진 일이다. 하나님이 이삭에게 나타나 아브라함 언약을 재확인. 이삭이 브엘세바에 제단을 쌓고 하나님의 이름을 부름. 아비멜렉과 다시 평화 조약.",
