    geo:"이스르엘 골짜기 동남쪽 산악. 갈릴리 산지와 사마리아 산지 사이를 동서로 가르는 넓고 비옥한 충적 평야다. 주요 교역로와 군사 행로가 지나 역사상 수많은 전투의 무대가 되었다 | 해발 508m | 사울·요나단 최후 전장",
