       bg:"왕정 수립기의 격변 속에서 다윗, 골리앗 대결을 둘러싸고 벌어진 일이다. 블레셋 장수 골리앗(키 약 2.9m)이 40일간 이스라엘을 조롱. 소년 다윗이 물매와 돌 하나로 골리앗의 이마를 쳐 쓰러뜨림. 여호와의 구원은 칼과 창에 있지 않음을 만천하에 선포.",
