       desc:"출애굽 초기 경로 — 라암셋→숙곳→에담→비하히롯→홍해. 하나님이 구름기둥(낮)과 불기둥(밤)으로 인도. 블레셋 길이 아닌 광야 길로 우회: 전쟁을 보면 백성의 마음이 변할까",
