    geo:"요단 동편 — 모압과 아모리 경계 강·깊은 협곡·사해로 흘러듦. 요단 강 동편의 숲이 우거진 고원 산지로 향유와 목초지로 이름났다. 깊은 협곡이 고원을 가르며 비교적 강수량이 풍부한 지역이다 | 고도: 해발 -300m (사해 유입부)",
