       ref:"수 14:6-15",
       bg:"가나안 정복기의 정황 속에서 갈렙 85세에 헤브론 정복을 둘러싸고 벌어진 일이다. 여호수아에게 헤브론 요청: 그 때 내가 강건하였고 오늘도 내가 여전히 강건하나이다. 아낙 자손(거인족)이 있어도 하나님과 함께하면 정복 가능. 끝까지 포기하지 않는 믿음.",
