       bg:"예수 그리스도의 공생애 가운데 빈 무덤 발견을 둘러싸고 벌어진 일이다. 큰 지진·천사가 돌을 굴려냄. 천사: '그가 여기 계시지 않고 그가 말씀하시던 대로 살아나셨느니라. 오라 그가 누우셨던 곳을 보라'. 여인들에게 제자들에게 전하라 명령. 기쁨과 두려움으로 달려감.",
