       bg:"초대교회 복음 확장의 흐름 속에서 1차 선교를 둘러싸고 벌어진 일이다. 회당에서 표적과 기사로 많은 사람 믿음. 그러나 불신 유대인들이 이방인 마음 자극→두 그룹으로 분열. 바울·바나바가 오래 머물며 담대히 주를 의지해 전도.",
